변경 이유: 진단의 chosen(TTC 기반 연속 속도 스케일링)과 direction 1–6을 따랐습니다. 새 함수 `_predictive_speed` 는 `_dynamic_pause` 로 TTC를 구하고, `ttc/_HORIZON` 비율로 줄인 속도 후보 세 개를 rollout margin으로 확인합니다. margin이 음수라도 TTC가 2 s 이상이고, 1.5 s 단기 예측이 안전하며, 멈춰 있는 것보다 크게 나쁘지 않으면 천천히 전진합니다. `_lidar_clear` 가 막히면 None을 돌려 속도를 0으로 둡니다. controller는 물체가 `_SAFE_DIST`(1.5→1.7 m) 안에 있으면 detour/pause 대신 이 함수를 먼저 부르고, None일 때만 기존 정지를 합니다. 정지가 2 s 넘게 이어진 완전 차단 상황에서만 기존 `_avoid_detour` 를 쓰고, escape 로직은 그대로 우선합니다. 이렇게 해서 근처 물체가 경로를 위협하지 않는데도 매번 멈추던 정체(진단 evidence의 106·121회 정지)를 없앱니다. 더 먼 물체에 막혀 `_safe_speed` 가 None일 때도 같은 함수를 정지 전 단계로 써서 같은 정체를 줄였습니다.

```python
def controller(t, pose, env):
    """Waypoint following + lidar mover tracking.  Priority: (1) evasion whenever standing still would be hit
    within _HORIZON, (2) mover within _SAFE_DIST -> TTC-scaled predictive speed (_predictive_speed); stop only
    when no scaled speed is safe, and fall back to a side detour only after 2 s of blocking, (3) goal alignment,
    (4) driving at the largest predicted-safe speed (TTC-scaled speed before pausing)."""
    if not hasattr(controller, "st"):
        controller.st = {"idx": 0, "pause_until": -1.0, "last_seen": -1.0, "wait_start": None,
                         "free_since": None, "prev": None, "vm": 0.0, "wz": 0.0, "tracks": [],
                         "last_f": None, "last_b": None, "raw": np.zeros((0, 2)), "ttc": float("inf"),
                         "esc": None, "esc_t": -1.0, "esc_until": -1.0, "detour": None,
                         "av": None, "av_t": -1.0}
    st = controller.st
    x, y, yaw = pose
    _update_motion(st, t, pose)
    _perceive(st, t, pose)
    M = _track_array(st, t)
    if len(M):
        st["last_seen"] = t
    n = len(_WAYPOINTS)

    # ---- target selection (waypoints / temporary detour / goal alignment) ----
    if st["idx"] >= n and math.hypot(GOAL[0] - x, GOAL[1] - y) > 0.45:
        st["idx"] = n - 1                       # pushed off the goal: go back
    aligning = st["idx"] >= n
    e_goal = _wrap_angle(GOAL[2] - yaw)
    if st["detour"] is not None and math.hypot(st["detour"][0] - x, st["detour"][1] - y) < 0.4:
        st["detour"] = None                     # detour reached: resume the waypoint path
    if st["av"] is not None and math.hypot(st["av"][0] - x, st["av"][1] - y) < 0.4:
        st["av"] = None
    wp = (GOAL[0], GOAL[1])
    tgt = wp
    if aligning:
        v_nom, w_nom = 0.0, _clamp(1.5 * e_goal, -0.6, 0.6)
    else:
        wp = _WAYPOINTS[st["idx"]]
        if st["idx"] < n - 1 and math.hypot(wp[0] - x, wp[1] - y) < 0.35:
            st["idx"] += 1
            wp = _WAYPOINTS[st["idx"]]
        tgt = st["detour"] if st["detour"] is not None else wp
        v_nom, w_nom, dist = _follow(pose, tgt)
        if st["detour"] is None and st["idx"] == n - 1 and dist < 0.25:
            st["idx"] = n                       # alignment starts on the next call

    # ---- evasion first (also while paused / aligning): standing still would be hit within _HORIZON ----
    hold, _ = _margin(pose, st["vm"], 0.0, 0.0, M, _HORIZON, 0.15)
    if hold < 0.0:
        if st["esc"] is None or t - st["esc_t"] >= 0.2:
            st["esc"] = _plan_escape(st, pose, M, wp)
            st["esc_t"] = t
        st["esc_until"] = t + 0.3
    if st["esc"] is not None:
        if t < st["esc_until"]:
            st["free_since"] = None
            if st["wait_start"] is None:
                st["wait_start"] = t
            return _escape_cmd(st, pose)
        st["esc"] = None                        # evasion over: rejoin the path safely
        if not aligning:
            _set_return(st, pose)

    # ---- mover within _SAFE_DIST: TTC-scaled predictive speed instead of detour/pause ----
    gap = _min_gap(pose, M)
    if gap <= _SAFE_DIST and not aligning:
        st["pause_until"] = -1.0
        if v_nom <= 0.0:
            return 0.0, w_nom, False            # turning in place toward the target (hold >= 0 checked above)
        vc = _predictive_speed(st, pose, tgt, v_nom, M)
        if vc is not None:
            _mark_free(st, t)
            return vc, w_nom, False
        # no safe scaled speed: stop; side detour only as a fallback after a long blockage
        st["free_since"] = None
        if st["wait_start"] is None:
            st["wait_start"] = t
        if t - st["wait_start"] > 2.0:
            if st["av"] is None or t - st["av_t"] >= 0.3:
                st["av"] = _avoid_detour(st, pose, M, wp)
                st["av_t"] = t
            if st["av"] is not None:
                st["detour"] = st["av"]
                v, w, d = _follow(pose, st["av"])
                if d < 0.2:
                    v = 0.0
                if abs(v) > 1e-3 and not _lidar_clear(st["raw"], v, 0.4):
                    v = 0.0
                return v, w, False
        return 0.0, 0.0, False
    st["av"] = None

    # ---- dynamic pause: only kept while a mover is within _SAFE_DIST ----
    if t < st["pause_until"]:
        if _should_pause(st, pose, M):
            st["free_since"] = None
            return 0.0, 0.0, False
        st["pause_until"] = -1.0

    # ---- goal alignment: finish only when nothing is about to reach us ----
    if aligning:
        if abs(e_goal) < 0.05:
            if _margin(pose, st["vm"], 0.0, 0.0, M, 4.0, 0.15)[0] >= 0.0:
                return 0.0, 0.0, True
            return 0.0, 0.0, False
        _mark_free(st, t)
        return 0.0, w_nom, False

    # ---- driving: rotate in place, or drive at the largest predicted-safe speed ----
    if v_nom <= 0.0:
        _mark_free(st, t)
        return 0.0, w_nom, False
    vc = _safe_speed(st, pose, tgt, v_nom, M)
    if vc is None:
        vc = _predictive_speed(st, pose, tgt, v_nom, M)
    if vc is not None:
        _mark_free(st, t)
        return vc, w_nom, False

    # ---- blocked by a farther mover: TTC-based pause; if blocked for long, go around the blocker ----
    pause, _ = _dynamic_pause(st, pose, M)
    st["pause_until"] = t + (pause if pause is not None else 0.5)
    st["free_since"] = None
    if st["wait_start"] is None:
        st["wait_start"] = t
    elif t - st["wait_start"] > 3.0 and st["detour"] is None:
        d = _stuck_detour(st, pose, M, wp)
        if d is not None:
            st["detour"] = d
            st["wait_start"] = None
    return 0.0, 0.0, False


_SAFE_DIST = 1.7


_TTC_SLOW = 2.0


_SHORT_T = 1.5


def _predictive_speed(st, pose, tgt, v_nom, M):
    """TTC-based continuous speed scaling.  ratio = clamp(ttc / _HORIZON, 0.2, 1) (1 when ttc >= _HORIZON);
    candidates v_nom * ratio * (1.0, 0.6, 0.3) (at least 0.15 m/s).  Returns the fastest candidate whose rollout
    toward tgt keeps margin >= 0 from every mover over _HORIZON.  If none does but ttc >= _TTC_SLOW, the slowest
    candidate that is safe over _SHORT_T and no much worse than standing still over _HORIZON is returned
    (re-checked every step).  None when nothing qualifies or the lidar strip ahead is blocked."""
    if v_nom <= 0.0:
        return None
    if not _lidar_clear(st["raw"], v_nom, 0.35):
        return None
    if len(M) == 0:
        return v_nom
    _, ttc = _dynamic_pause(st, pose, M)
    ratio = 1.0 if ttc >= _HORIZON else _clamp(ttc / _HORIZON, 0.2, 1.0)
    mh, _ = _margin(pose, st["vm"], 0.0, 0.0, M, _HORIZON, 0.15)
    ns = int(round(_SHORT_T / 0.1)) + 1
    slow = None
    for fac in (1.0, 0.6, 0.3):
        vc = _clamp(v_nom * ratio * fac, min(0.15, v_nom), v_nom)
        xs, ys, hs = _rollout(pose, st["vm"], _HORIZON, tgt=tgt, vmax=vc)
        m, _ = _traj_margin(xs, ys, hs, M, 0.15)
        if m >= 0.0:
            return vc
        if ttc >= _TTC_SLOW and m >= mh - 0.3:
            ms, _ = _traj_margin(xs[:ns], ys[:ns], hs[:ns], M, 0.1)
            if ms >= 0.0:
                slow = vc
    return slow
```
